INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 128, '一些诗词 元朝', '../upload/image/20180923/20180923102310_28105.jpg', '<p></p><p><span style="color:#000000;font-family:Arial;font-size:24px;font-style:normal;"><span style="color:#000000;font-family:Arial;font-size:24px;font-style:normal;"><span style="font-family:Tahoma;font-size:18px;">元朝</span><br/> </span><span style="color:#000000;font-family:Arial;font-size:36px;font-style:normal;"><span style="font-size:24px;"><span style="font-family:Tahoma;font-size:18px;">蒙元开疆三千万，帝国雄霸阔无边 。</span><br/> </span><span><span style="font-size:24px;"><span style="font-family:Tahoma;font-size:18px;">声威随云南入海 ，铁骑横陈西极天。</span><br/> </span><span><span style="font-size:24px;"><span style="font-family:Tahoma;font-size:18px;">岭北辽阳版籍内，四大汗国拱卫全。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 国人自此才刚烈，宜将勇猛再复原。</span></span><br/> <span><br/> <span style="font-size:18px;"><span style="font-size:36px;"><span><span><span style="font-size:24px;"><span style="font-size:36px;"><span style="font-size:36px;"><span style="font-size:24px;"><span style="font-family:Tahoma;font-size:18px;">注释：</span><span style="font-size:24px;"><span style="font-family:Tahoma;font-size:18px;">岭北辽阳”，岭北行省和辽阳行省，占今天俄罗斯全部领土的2/3还多。其资源丰富的程度，不得不知。 别说内蒙古，就是外蒙古也在岭北行省的最南部。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> “四大汗国”，臣服于元朝，这是蒙古怀柔，让他们高度自治的四个幅员也算辽阔的国家，这样可以缓解元朝外部的军事压力。</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:24px;font-style:normal;font-weight:bold;"><span style="color:#000000;font-family:Arial;font-size:36px;font-style:normal;font-weight:normal;"><span><span><span><span style="font-size:18px;"><span style="font-size:36px;"><span><span><span style="font-size:24px;"><span style="font-size:36px;"><span style="font-size:36px;"><span style="font-size:24px;"><span style="font-size:24px;"><strong><br/> </strong></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:24px;font-style:normal;font-weight:bold;"><span style="color:#000000;font-family:Arial;font-size:36px;font-style:normal;font-weight:normal;"><span><span><span><span style="font-size:18px;"><span style="font-size:36px;"><span><span><span style="font-size:24px;"><span style="font-size:36px;"><span style="font-size:36px;"><span style="font-size:24px;"><span style="font-size:24px;"><img alt="图片" src="http://r.photo.store.qq.com/psb?/V14B0ohH4bESJx/k84bD.Mb3.4OpDsQqXW51wq2Nf90d9Obc9yJ5eh0jgM!/o/dGCD6Ey7DwAA&amp;bo=kAOAAkAGYgQBABY!" style="width:870px;height:610px;"/></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:36px;font-style:normal;font-weight:normal;"><span><span><span><span style="font-size:18px;"><span style="font-size:36px;"><span><span><span style="font-size:24px;font-weight:bold;"><span style="font-size:36px;"><span><span><span style="font-size:36px;"><span><span><span style="font-size:24px;font-weight:bold;"><span><span style="font-size:24px;font-weight:bold;"><br/> </span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:36px;font-style:normal;font-weight:normal;"><span><span><span><span style="font-size:18px;"><span style="font-size:36px;"><span><span><span style="font-size:24px;font-weight:bold;"><span style="font-size:36px;"><span><span><span style="font-size:36px;"><span><span><span style="font-size:24px;font-weight:bold;"><span><span style="font-size:24px;font-weight:bold;"><br/> </span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 139, '讲课内容----在一家合作的货代哪里的讲课内容（节选）', '../upload/image/20180923/20180923102956_15894.jpg', '<p></p><p align="center" style="text-align:center;"> <b><span style="color:#FF0000;font-family:微软雅黑;font-size:18pt;font-weight:bold;"><span>讲课内容</span>----<span>在一家合作的货代哪里的讲课内容（节选）</span></span></b></p> <p style="text-indent:36pt;"> <span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>去讲课前</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，有人</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>说</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>：</span>”</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>可不拿自己当外人</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>人家那个不比你知道的多。人家给你八年出一票货物</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>还</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>要</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>给你捧场</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>故意给你个面子叫你去讲课，你还当真了。</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;">”</span></p> <p><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>我回答</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>：</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>（</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>就</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>怕</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>认真二字</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>出口进口都做，票票和货代合作</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>今天的谈话我认为可以给诸位带来一些启发</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>）</span></span></p> <p></p> <p><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>态度问题</span></span></u><u><span style="color:#000000;font-family:微软雅黑;font-size:12pt;text-decoration:underline;"><span>：</span> </span></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>焦首朝朝还暮暮</span></span></u><u></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>煎心日日复年年</span></span></u><u></u><u></u><u></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>星临万户动</span></span></u><u></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>月傍九霄多</span></span></u><u></u></p> <p><u><span style="color:#000000;font-family:微软雅黑;font-size:12pt;text-decoration:underline;"><span>不是你进入一家大型体面的公司你很骄傲，而是公司因为拥有你而感觉到骄傲</span></span></u></p> <p><span style="color:#000000;font-family:仿宋;font-size:12pt;"><span>天天感觉自己货代做的不错，怎么没有单子，怎么客人做几次就不做了，谁都没得罪，为啥和我合作的客户稳定的不多，大单子不多。</span></span></p> <p><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>货代窗口找来：</span></span></p> <p><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你都是</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>蒋总有啥货物吗？</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>怎么给你帮忙报价。</span></span></p> <p><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>人家都是</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>啥名字来自啥公司</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>优势航线是啥，然后把自己优势航线的价格</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>报</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>出来</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>很多</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>行价格，最后看到一个其中有一个是大连到迪拜</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>这个不是</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>我上周走的吗上次我走的价格是</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">600</span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>人家现在给的是</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">400</span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>兴趣立刻来了，立刻联系</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>而且</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>不就成单子。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你和人家的水平</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>高下立见。人家事半功倍</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>。</span></span></p> <p style="text-indent:24pt;"> <span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>人家又来电话了说</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>：</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>最近老是撞船</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>我这个电话也许多余</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>但是建议您一定买保险。（</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>全部考虑发货人权益）。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你从来电话我都是问问</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>有货没有</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>啥时候能给你走一票</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你完不成销售任务了（</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>全部想着你自己发财）</span></span></p> <p style="text-indent:24pt;"> <br/></p> <p style="text-indent:24pt;"> <br/></p> <p style="text-indent:24pt;"> <br/></p> <p><b><span style="font-family:Calibri;font-size:12pt;font-weight:bold;">8.</span></b></p> <p><b></b><b><span style="font-family:Calibri;font-size:12pt;font-weight:bold;"><span>一些体会：</span></span></b><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>以上的情况</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>到底该如何去理解，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>如何找到解决的办法，</span></span></p> <p><span style="color:#000000;font-family:Calibri;font-size:12pt;">a </span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>）</span></span><b><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;"><span>人人都有自己不会的地方，</span></span></b><b></b><b><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;"><span>但是都不会明说这个地方我不会或者是</span></span></b><b><span style="color:#000000;font-family:微软雅黑;font-size:12pt;font-weight:bold;"><span>那个</span></span></b><b><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;"><span>地方我不行</span></span></b><b><span style="color:#000000;font-family:微软雅黑;font-size:12pt;font-weight:bold;"><span>，</span></span></b><b><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;"><span>我不如你</span></span></b><b></b><b><span style="color:#000000;font-family:微软雅黑;font-size:12pt;font-weight:bold;"><span>。</span></span></b><b><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;"><span>你的谈话能否带有提示解释的性质，能否带有成型的方案共别人挑选</span></span></b><b><span style="color:#000000;font-family:微软雅黑;font-size:12pt;font-weight:bold;"><span>，</span></span></b><b><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;"><span>这样成功更高</span></span></b><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>（</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>比如，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>出口商不知道啥是</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">14</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>天自由港时间</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">/</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>也就是免用箱时间</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你赶紧打电话给出口商</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>告诉他去印度的经常需要</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">14</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>天自由港时间，出口商也许是第一次出口，但是这个时候他不一定好意思问你为啥，怕你说他出口啥都不懂。你就应该接着说，因为印度人办事效率低</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>港口建设破破烂烂</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>、</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>清关缓慢，一旦超过</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">7</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>天的天然免用箱时间</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>就会产生费用，而且费用与日俱增</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>后期加倍</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>给客人在目的港口增加不必要的成本费用。如果现在订舱时候申请了，一分钱不要</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>、</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>而且客人也</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>可以</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>在目的港从容清关，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>无论这话你说了，出口商申请与否，代表你做这个事情了。这样你作为货代</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>这个电话是让人鼓舞的</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>也是让你自己高兴的。</span></span></p> <ol> <li style="color:#000000;font-family:微软雅黑;font-size:12pt;font-style:normal;font-weight:bold;"> <p style="color:#000000;font-family:宋体;font-size:12pt;font-style:normal;font-weight:normal;"> <span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>最傻的就是你这样的傻逼，以为发货商没有提出来</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>反正自己的猪脑子也想不起来，干脆得过且过，干脆不提也不问。你不知道</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>要是你电话提到这个事情，出口商</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>：</span></span><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>第一</span></span></u><u><span style="color:#000000;font-family:微软雅黑;font-size:12pt;text-decoration:underline;"><span>：</span></span></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>会认为你专业，知识丰富啥都知道，而且操作的单子无数，在你手里走他放心</span></span></u><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>。</span></span><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>第二会认为你体贴细致，什么注意事项都不要出口商自己想</span></span></u><u></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>你都能想的到，而且会及时告诉他，不会给坏事情</span></span></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>第三会认为你真的是自己人就是他要找的知冷知热的货代。能和你合作他除了希望事情办完后立刻支付前给你来表达对你的谢意和对你的忠诚，还会十分尊重你</span></span></u><u></u><u><span style="color:#000000;font-family:Calibri;font-size:12pt;text-decoration:underline;"><span>因为尊重你就是给他自己造福，信任你就是和得到金钱划等号。</span></span></u></p> <p style="color:#000000;font-family:宋体;font-size:12pt;font-style:normal;font-weight:normal;"> <span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>然而你这样的傻逼之人</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>、</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>居然破天荒的认为人家都没提</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">14</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>天以自由港</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你提出来</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>万一出口商想申请</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你还要找他盖章签字还要找船公司</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>而且做完这些事</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>、你还是全程免费，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你一分钱也不能多收，干了也白干。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你为你知道或者忘却这个事情</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>以至于不去办理</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>而陶醉的</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>胜利的</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>喜悦的</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>或者相反的表情</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>盲目的</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>毫无知觉的</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>、</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>呆头呆脑的</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>走路都不能成直线</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>以为世界上钱真好赚，一切你都钯里纂。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>结果，货物到港，出口商清关延迟，港口罚款。客人清关的货代告诉客人</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>可以在发货港口申请</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;">14<span>或者</span><span>21</span><span>天免用箱</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>，但是你在订舱时候没有申请，现在申请不了啦</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>船公司推脱不给申请了</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>你也傻眼没辙了</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>无端给客人增加费用，下次只要有人申请了</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;">14</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>天自由港时间</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>客人不但你这家货代不用了，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>连这家出口商都不采购了，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>就为这事情是丢失客户，大家都输了。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"> <span>痛心疾首</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>而且事情往往是出现这个坏的结果。本来可以继续的业务，最后没有了。</span></span></p> <p style="color:#000000;font-family:宋体;font-size:12pt;font-style:normal;font-weight:normal;"> <span style="color:#000000;font-family:Calibri;font-size:12pt;">B</span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>）</span> </span><b><u><span style="color:#000000;font-family:微软雅黑;font-size:12pt;font-weight:bold;text-decoration:underline;"><span>和别人打交道，特别是商业行为，一定要记住至高无上的法宝，那就是处处示弱，</span></span></u></b><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>这个很好理解。比如一家货代，怎么说他，他都服服帖帖，给他讨价还价，无论便宜多少，这家货代你都能便宜一些，哪怕是</span>100<span>元。 另一家货代，总是牛皮哄哄，岑头咧怪，而且完全是靠扣提单强行去开账单，强迫支付，两家货代就在你面前，你要出货了， 老板问你选择谁？ 你肯定选择第一家，你会给老板说，第一家货代我叫他干啥他干啥，从来不敢反样，容易控制，而且忠心耿耿。</span></span></p> <p style="color:#000000;font-family:宋体;font-size:12pt;font-style:normal;font-weight:normal;"> <span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>我做国外的业务，国外客人看不见我、摸不着我，我全靠完成客人交给我的任务，对客户服服帖帖，踏踏实实，不搞阴谋诡计，</span> <span>对复杂单据单证，突发认证等跑断腿也帮助客人办理好，才得到客人的信任和才一直做客人的单子的。靠的就是处处示弱，给客人一种完全可以控制住我的感觉，给客人一种我在他面前从来不敢忤逆他，不敢欺骗他，更不敢给他瞎报价的一种可靠的感觉。你也许和我有一样的感觉</span> <span>只是你没有像我一样总结出来，但是你在实际使用这个办法的时候，却老是力不从心，这是为啥，因为我是用心来办事，臣服于客人商业交往的真理，你是用计策来办事，你服务于你的利润多少来决定你软弱的程度，当利润不是暴利的时候，你的耐心就消失，</span> <span>更不要提你能服务了。</span></span><b><u><span style="color:#000000;font-family:微软雅黑;font-size:12pt;font-weight:bold;text-decoration:underline;"><span>商业的本质是控制，你的客户能够控制住你，他就会选择继续和你打交道，一旦他感觉到控制不住你，无论你价格再好，他也不敢和你做。</span></span></u></b></p> <p style="color:#000000;font-family:宋体;font-size:12pt;font-style:normal;font-weight:normal;"> <span style="color:#000000;font-family:Calibri;font-size:12pt;">C</span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>）</span> </span><b><span style="color:#000000;font-family:微软雅黑;font-size:12pt;font-weight:bold;"><span>主动汇报制度，这个很重要，绝对不能轻视。想挣别人的钱，就要把事情给人家说的清清楚楚、明明白白。一本糊涂账，或者漫不经心、都自我毁灭。</span></span></b><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>啥叫主动汇报，不就是人家找你走货，但是人家又想知道、出口货物的流程到哪一步了，</span> <span>问你，又不一定能找到合适的时间，比如刚想到问你，发现时间是晚上半夜</span>12<span>点，怎么去问你，白天上班人家出口商有可能在接待客户，没来得及问你。不问你、不代表货主不关心。如果你能主动</span><span>QQ/</span><span>微信留言，告知事情进行到哪一步了。说的尽量详细一些，特别是需要提前叫货主准备的资料，或者是你不能理解的货主资料的文字说明啥的， 都要表达清楚， 把当天下来的或者你手里到这一时刻为止，下来的单据， 特别是</span></span><u><span style="color:#000000;font-family:微软雅黑;font-size:12pt;text-decoration:underline;"><span>整套报关资料齐备与否，船公司提单，确认单，邮箱要求，保函等单据</span> <span>和海关的查验单，报关单核对文本和正本，放行通知书，目的港代理</span></span></u><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>等等，都能够立刻给到相应的货主手里，货主从心里自然服你，这也是你证明你收钱你办事的最好的材料，或者是亲自打电话货主，主动汇报一切相关信息，并从你的这些汇报里面留意货主的人生观、价值观、个人修养、专业知识、个人素质，以及他产品的特性和他本人的处境等等，这是多好的你和货主沟通的场合和机会，你以对公业务为主要内容，不断挖掘货主的出口地区，出口数量，出口习惯、和常用货代你都能套出来，这样不比你单独打电话叫人家告诉你，人家经常出口啥地方，有多少数量，更容易得到真实消息吗？本来是你的权限，你是完全不利用，非要默不则声，处处等着人家来找你，花钱找你服务，还要老是在你屁股后面找着你，</span> <span>你不嫌烦、但是人家觉得无趣。鬼才找你做下次单子呢。</span> <span>（</span> <span>当然有的货主不喜欢货代打扰。</span> <span>你就少啰嗦，一般不出事，</span> <span>可以不联系，但是我认为谁都会关心自己的货物，你联系了，对你的货代服务还是有帮助的。）</span></span></p> <p style="color:#000000;font-family:宋体;font-size:12pt;font-style:normal;font-weight:normal;"> <span style="color:#000000;font-family:微软雅黑;font-size:12pt;">d</span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>）</span></span><b><u></u></b><b><u><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;text-decoration:underline;"><span>这是最重要的，</span></span></u></b><b><u></u></b><b><u><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;text-decoration:underline;"><span>那就是增加预见性</span></span></u></b><b><u></u></b><b><u><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;text-decoration:underline;"><span>防患于未然</span></span></u></b><b><u></u></b><b><u><span style="color:#000000;font-family:Calibri;font-size:12pt;font-weight:bold;text-decoration:underline;"><span>凡是预则立不预则废</span></span></u></b><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>。把前面道路上可能出现的风险和问题</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>都最大限度的预料到，然后告诉相关的当事人。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>叫当事人提前采取措施，就是到时候问题真的出现了，当事人</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>回忆</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>出来你曾经预料到和提醒过他，虽然他悔不当初</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>但是也会从心底感谢你的。出口商</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>即</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>便是自己吃亏了，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>也不会影响下次和你合作的。</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>比如：这里就举几个</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>例子。先</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>从基础的单据说起</span></span><span style="color:#000000;font-family:微软雅黑;font-size:12pt;"><span>，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>完全可以规避的单据问题的错误，</span></span><span style="color:#000000;font-family:Calibri;font-size:12pt;"><span>因为下面我还会提到进口的事例：</span></span><span style="color:#000000;font-family:仿宋;font-size:12pt;"><span>（进口里面的清关时候的单据细节，</span></span><span style="color:#000000;font-family:仿宋;font-size:12pt;"><span>比如，国外提供的</span>FTA/优惠关税证书上面的总数量即净重和毛重和国外的提单发票合同上面的总数量即净重和毛重有出入的情况；</span><u><span style="color:#000000;font-family:仿宋;font-size:12pt;text-decoration:underline;"><span>国外提供的</span>FTA/优惠关税证书上面打印过细，导致FTA分两个独立的证书，造成在中国海关清关需要分两票清关的情况</span></u><span style="color:#000000;font-family:仿宋;font-size:12pt;"><span>；国外预先或者合同上面不能显示合同号发票号等信息造成国内清关单据在这个上面出错的情况，或者是国内海关清关时候要求的货物的申报要素和货物的材质的详细说明；国外单据不能及时提供全部正本纸质盖章签字版本的单据情况；提单，</span>FTA等需要国外确认和提供的，但是上面有错误需要更改，国外却搪塞或者迟迟不能更改的情况，等等）</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 140, '岳飞', '../upload/image/20180923/20180923102404_57040.jpg', '<p><span style="color:#000000;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:bold;background-color:#FFFFFF;">看电视剧 “精忠岳飞” 后随笔 </span><span style="color:#000000;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><br/> <span style="font-size:24px;"><span style="font-weight:bold;"><span style="font-family:Tahoma;font-size:18px;">岳飞</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;"> 金虏呼啸碎中原，岳军迎头杀敌顽。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 锐旅过河掀血浪，复土中原气贯天 。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 联结河朔千秋业，三军直指二圣还。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 解甲释权英魂去，大宋中兴至此完。</span></span><br/> <span><br/> <span style="font-size:18px;"><span style="font-family:Tahoma;font-size:18px;"> 岳飞是我国民族英雄序列中的耀眼明星，是整个南宋唯一一个以攻为守的将军，也是唯一一个能够和金国骑兵进行大兵团打野战的统帅，岳飞去后，南宋朝廷从此小。（岳飞葬在西湖，杭州西湖从此重。）再也不能独立起来了，再也不能再对外战争中有所前进了。 </span><span style="font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">岳飞文韬武略。文的方面，满江红怒发冲冠一首词至今是中国家喻户晓人人能诵读的名篇，千百年来激励后人，经久不息。三十功名尘与土，把名利看得十分淡然，八千里路云和月 把纵横沙场南征北战写的潇洒飘逸。岳飞武的方面，自己带领不到50人 杀入金军大营，能够再突出重围，返回来。这在中国历史上是极端罕见的。足见岳飞智勇和韬略。常言道：”</span><span style="color:#333333;font-family:Tahoma;font-size:18px;">兵家之要，在于出奇，不可测识，始能取胜。阵而后战，兵法之常，运用之妙，存乎一心。“</span><br/> </span><span style="font-family:Tahoma;font-size:18px;"> 岳飞是战略家 </span><span style="font-family:Tahoma;font-size:18px;">，打仗就要死人，而且战死也是光荣的，但是如果能够在大的战略上预见到，不被对方战略钳制，打埋伏；能够在具体的战役上，适当安排各个军团或者各个部队，分队，始终不让对方站到先机，则战争不能使得主帅或者指挥者轻易被擒或者被战死。而且一旦受到埋伏</span><span style="font-family:Tahoma;font-size:18px;">，</span><span style="font-family:Tahoma;font-size:18px;">指挥者能够立刻预见到，这个埋伏的规模和怎么突破，则也不能被擒或者被战死</span><span style="font-family:Tahoma;font-size:18px;">。</span><span style="font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">岳飞这些上面都是过关的。这是一个主帅或者领导者，应该具备的才能。</span><span style="text-decoration:underline;"><span style="font-family:Tahoma;font-size:18px;">岳飞 诸葛亮 毛泽东，粟裕等，不是因为战争没有牺牲靠的是偶然和机会，而是因为在他自己的年代，没有韬略能够超过他们，他们不但对自己的国家里面的事情了如指掌，而且对于对手的国家的事情也了如指掌。所以无论自己的指挥部设在什么地方，都不可能遭到敌人的伏击， 和就是遭到伏击，总有一个人，一件事，一条路，一支军等这样的奇人奇事和奇兵及时出现，化险为夷。这不是什么有神论，而是整个当时的自然条件和社会条件总有被他们的韬略所无意运用到的地方，因而就在这个地方使得他们能够存在下去。不被消灭。</span></span><span style="font-weight:bold;"><span style="font-family:Tahoma;font-size:18px;">自己的位置和自己敌人的位置，无论远近，总是隔着一个神奇的鸿沟，使得对手无论用尽什么办法，始终不能逾越。这个鸿沟是可以起死回生的鸿沟，哪怕就是面对面，也能制造出这个鸿沟。而且让对方无论如何不能超越。</span><br/> </span><span style="font-family:Tahoma;font-size:18px;"> 岳飞用兵，打的准，而且极具战略眼光，这使得整个金朝没有能与之匹敌。1. 如果岳飞就100人，他会主动设伏比自己小些的金朝小分队。这样只要有机会，只要岳飞自己能做主，立刻这样做。所以岳飞的成绩天天都有，大家也都能看到。就这个魄力和勇气，就堪称军队的优秀指挥者。2. 如果岳飞就100人，而且受到别人的领导，受到的这个领导对岳飞的用兵有极大的限制，这个时候，岳飞会选择一些时机，精心研究对方的心态，装备，以及攻打对方的时间和方法，所以自领导岳飞的人看来，老是不经意拿到了岳飞制胜的信息，给这些领导者总是喜出望外。3. 如果岳飞就100人，而且受到别人的领导，并且受到别人的指使或者命令，去攻击具体的地点或者具体的人，这样岳飞就会，以边激励将士，一边就这个对手的情况去找到破绽，并且想一些办法去迷惑敌人或者激怒敌人，让敌人自己暴露出来，然后攻击之。4. 如果岳飞就100人，而且受到别人的领导，或者自己领导下，面对比自己多数倍的敌人，或者面对自己必须就拯救的拖累（ 比如 保护城中的百姓，或者保护出事金朝的人，或者保护昏聩的皇上），这时候 命题就是无论岳飞有多少兵，或者有多少能力，就是说岳飞的兵力和力量已经固定，而攻击的目标无穷大，这样岳飞就会采取空城计或者是声东击西等战略战术，吧自己的军队仅仅在一个最需要的地方表露出来，用于迷惑敌人，在敌人的错觉中 达到自己的战略要求。5. 如果岳飞就100人，而且受到别人的领导，面对比自己多数倍的敌人，并且就只有一次机会，（ 比如最后大朱仙镇后，立刻就能攻打汴京。 但是朝廷下12到金牌圣旨和切断岳飞岳家军的粮草，吧配合岳飞岳家军的友军也撤掉，这样吧岳飞的实际兵力削弱，使他处于孤立无援的地步，而且有可能是将要受到友军攻击的地步），这时候岳飞就会采取险中求胜，吧自己对对人熟悉的情况 立刻转化为战斗力，吧军队补给有原来的取自朝廷改成现在的取自对手。吧战场有原来的固定作战改成创造战场，以便完成战役胜利</span><span style="font-size:16px;"><span style="font-family:Tahoma;font-size:18px;">。（这个战役，因为岳飞被杀，没有组织，但是岳飞组织的将要进攻的某些端倪，比如在他上书给朝廷的书信， 和找部下去做一些有目的的事情，还是 可以揣测出来的。如果非要举个例子，那就需要用解放战争的事例来说明一下：但是解放战争不是岳飞打的， 那是毛主席带领共产党打的。这个是事实，但是战役的战略指导思想，和战略布局是相通的。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 日本投降后，整个战场形势是： 国民党整个战略基地龟缩在西南的，蒋介石的军队凡是和日本打仗的 在打仗后全部改成对共产党军队的监视上面， 想陕甘宁边区，周围都是国民党军队，山东解放区也是如此。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 整个抗日战争胜利后，蒋介石的军队是430万，共产党是130万。共产党的军队分别八路军和新四军。八路军那是国民党承认的，也是红军长征的主力发展起来的，新四军在1942年遭到过皖南事变围剿，为了长征能成功，当时王明博古 李德吧能打仗的队伍都带走了，所以大家都认为新四军要弱一些。鉴于抗战胜利，内战爆发。国民党把共产党各个解放区都围得水泄不通，国民党那是志在必得。读者想象，美国佬为什么要帮助蒋介石，那是算定蒋介石必胜，在1946年美国的科技很发达了，又能立刻染指中国，对中国的情况摸得比自己还熟悉。就连美国人都认为蒋介石能赢，苏联不敢直接支持共产党，也是苏联认为共产党不能在苏联认为的时间内打败国民党，而美国和蒋介石都认定的事情，还能错吗？日本走后，东北空出来。就这样蒋介石要夺取东北了。共产党也不知道内战的共产党能否在从海南到山海关，从江苏到新疆的解放区能否打赢，所以争相夺取东北。蒋介石还都南京。当然是吧在高邮等地的苏中解放区的粟裕先吃掉，想吃到粟裕主要是新四军军力弱，距离南京近，又威胁南京和容易消灭。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 棋局就是这样，要是 完全按照国名党的打法，就是国民党进攻，共产党就还手，因为国民党强，共产党弱。那这样的仗美国人和蒋介石都能看到，国民党能赢。但是毛浙东不这样，毛主席按照自己的习惯，一把识破伎俩，立刻做出2个千里跃进，一个是中原解放区的刘邓大军挺进大别山，一个是林彪等挺进东北。这2个挺进都是千里跃进。到外线作战，没有根据地和后援。能出这一手的，在战争中，特别是野战中，那就是高手了。这是毛主席的大战略，也是打破国民党排兵布阵的一个战略的实际运用。这2个千里跃进。发挥的力量很大，而且收效很好，无论的中共将领还是国名党军事能人都很佩服。共产党完全甩开膀子，可以大打了。原来的死局，现在变活了。我解放军可以吧全国作为战场，东奔西突了。拿到这个成绩，毛主席很高兴，就命令正在被国民党打的苏中的粟裕部队，越过长江，打到外线。来第3个千里跃进，收到更多的奇效。这样粟裕部队也就不能被消灭了，结果粟裕不同意。提出要在就地歼灭国民党，而且提出在江北在中原和国民党战略决战。这个建议在当时能够理解的人没有，包括毛主席。正在东北的林彪，陆续接到了粟裕在苏中打的几仗的战果，不但粟裕不能被消灭，而且还能壮大，林彪说 “粟裕能打的仗，我打不来”，这个话就透露了能够自己创造战场的共产党，统帅毛泽东和得意弟子林彪都参不透粟裕的玄机。粟裕这个想法立刻汇报给了毛主席，说去江南没有后方，十万人以卵击石，不等到达江南，就被消灭一半了。毛主席立刻回答 长征也没有后方 我们没被消灭，刘邓没有后方也没被消灭，怎么就你能被消灭。粟裕吧自己的想法汇报给中央，从此从苏中达到苏北，然后达到鲁西南，最后把张灵甫74师和济南王耀武都拿下了。小淮海战役变成了大淮海战役，形成的2个野战军的合并。粟裕变成指挥中国人民解放军兵团人数最多的人，最高峰达到84万人。原来共产党集中兵力的办法被粟裕活用了。（主要表现在，在较短的时间内形成打击敌人的绝对优势，而且以极端快的速度吧对方吃掉，最典型的例子就是孟良崮打74师。74师居国民党嫡系部队5大主力之首。张灵甫师长用兵也出神入化。粟裕围住他，他把粟裕的全部主力部队也都吸引到自己周围，叫蒋介石派更多的部队再围住粟裕，这样中心开花，一举拿下粟裕。但是张灵甫哪里知道，粟裕就是在他把这个战略想出来也相通了之后，就立刻把他吃掉了。就等于立刻围住张灵甫，不管张灵甫认为还是不认为能否吃掉它，反正就是在极短的时间内，一把吃掉，没有任何来得及反应，就消灭掉了。吧74师吃掉后，毛主席说，这一仗的胜利有2个人不知道，一个是我毛泽东，一个是蒋介石。 毛泽东和蒋介石打仗，打了20年，而且孟良崮战役，2位统帅都是亲自指挥的，居然这2个人都不知道这场战役的结果。这说明，毛泽东对集中兵力的最大威力还是第一次见到，蒋介石对于如此高度机械化和高度机动灵活和高度指挥适当的师团，而且自己是作为进攻的部队去的，等于自己有十足的把握去打人家，都能在如此短的时间内被人家报销，也是第一次见到）。抓住国名党守城市和守铁路的要点 打了几仗， 是自己转危为安。按照自己严格计算的战争进程打了七战七捷 豫东战役 临沂战役，孟良崮战役，济南战役。最后高潮淮海战役渡江战役，此共产党打败国名党） </span></span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;"> 但是南宋小朝廷没有抓住岳飞这个天才，最终自毁长城。在南宋的起初的岁月里，南宋也并不算是最糟糕的，那时候的君臣多少还有些骨气，还敢抗争。但是整个大局到了向桧这样的人染指或者领导后，灾难就会立刻出现。</span><span style="font-family:Tahoma;font-size:18px;font-weight:bold;">而且在整个中国和世界的历史上，一度在一个时期和多个时期内颠倒黑白，忠奸不分</span><span style="font-family:Tahoma;font-size:18px;">。</span><span style="font-family:Tahoma;font-size:18px;text-decoration:underline;">这是因为在体制内满足不了或者禁止了卖国者和腐败者的贪欲，他们不得不在体制外攫取更多的见不得人的勾当和利益，因而在体制内的人看来好像是黑白颠倒、是非不分了。其实这是某个人，某些人或者某些集团罪恶的黑手遥控的结果。而且这种现象存在于几乎是整个人类社会，也存在于几乎是所有的社会制度中。这些勾当害死国家无数的政权，团体和个人等。这些卖国者和腐败者所采取的罪恶的办法，从一开始绝大多数就和血腥的暴利结合起来，或者和欺骗，威胁，恐吓等结合起来，用制度和个人在正常情况下、所不能接受的办法来实现，因此被这些卖国者和腐败者染指过得国家，则国家飘零孱弱，行业则行业萎靡颓废，个人特别是女性，则极端难以回归正常的社会和个人生活。这个顽疾并不是物质的匮乏、而是制度设计的不足和监督的不足。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 秦桧是这样想的，对外给金人办事，留着自己的后路，在南宋投合小皇帝，给自己升官。而且南宋小朝廷，已经没有什么很重要的人才了，特别是没有厉害的文臣，所以秦桧可以很快爬上去，秦桧爬上去靠的办法很简单。就3个方面：一是 传递情报给金人。向金人屈膝投降，使得金人在有民族气节的人身上得不到的，在秦桧身上得到。这是因为南宋实在灾难深重，只要略略有些良心的人，都不会给金人当奸细，所以在南宋高层，秦桧这个奸细首屈一指。二是 南宋小朝廷怕自己的皇帝宝座别被从五国城解放出来的二圣在拿走了，始终不敢解救自己的老爹和哥哥（ 徽钦二帝）。所以 只要是真想收复中原的，小皇帝就会杀谁，来保住自己的小利益。 三是 有岳飞等武将的能征善战，使得金人灭亡不了南宋，只能和南宋议和，盗取利益。这样岳飞一打，小皇帝就支持，不支持小皇帝就要被金人搜山检海，被金人打的处处跑，而且打的越来越怕。这样岳飞一打大胜，小皇帝就害怕，怕岳飞赢回二帝，吧自己的位置占了，又怕岳飞称帝。所以 岳飞小胜，金人打不过去， 就议和，所有大臣都认为岳飞能大胜，都想出了南宋这口气，就都支持用武，不支持议和。 秦桧这样的一个卖国贼，要求议和。当岳飞大胜，金人打不过去， 只能议和，所有大臣都认为岳飞能大胜就能打败金人，不但出了南宋这口气，恢复南宋的疆土，就都更支持用武，绝不支持议和。但是小皇帝怕二帝回来和岳飞称帝， 秦桧这样的一个卖国贼，迎合皇帝懦弱的心态，要求议和。往往秦桧最能得到皇帝的心，而且议和被采纳，秦桧最后一手遮天。秦桧不择手段的前途，大家看的都很清楚，只是南宋小皇帝自欺欺人，不知道岳飞死，无人能节制卖国贼秦桧，最终小皇帝也是要被秦桧出卖的，</span><span style="font-weight:bold;"><span style="font-family:Tahoma;font-size:18px;">因为像秦桧这样的卖国贼，只要卖国才能延续自己的政治生命，一旦卖国停止，生命也就停止了。</span><span style="font-weight:normal;"><span style="font-family:Tahoma;font-size:18px;text-decoration:underline;">而且在出卖国家和民族的利益上是极端疯狂的，他们在毁灭一切正义力量和一切正直的人这一方面，手段是极端凶残的，往往这种手段超出一切法律的严厉禁止的（比如谋反罪等莫须有的罪名），人伦所不能允许的（比如杀人九族和扩大打击对象或者对女性的极端残暴等），和单独肉体所不能承受的痛苦（比如凌迟等）。</span><span style="font-weight:bold;"><span style="font-family:Tahoma;font-size:18px;">所以，武将不进行清君侧，而是兵变皇帝，这样对于封建社会的忠君体系加了一把锁，使之产生悲剧。</span><br/> </span><span style="font-family:Tahoma;font-size:18px;text-decoration:underline;">这就告诉我们一定要对这种卖国贼保持极端的清醒，和保持高度的警惕，保持好团结和对这种卖国贼所能采取的行动做个预先的估计，并且找到切实能够跳出这些卖国贼所设计的圈套的办法，做到提前动手，将计就计，以防止被动。</span><br/> <br/> </span></span><span style="font-family:Tahoma;font-size:18px;"> 岳飞一心为了国家中兴，收复失地。一生都在实践这件事。打到朱仙镇，和金军在汴京进行一次决战，收复汴京和收复中原，然后夺取燕云十六州，然后就可以救出二帝，完成自己毕生的心愿。就着这个时候，12道金牌令。要求班师回朝，然后解除兵权，然后杀害。</span><span style="font-weight:bold;"><span style="font-family:Tahoma;font-size:18px;">因为像岳飞这样的忠臣良将，只有精忠报国才能延续自己的政治生命和自然生命，一旦报效祖国，奉献人民停止，不能为人民的解放、自由、富强，幸福和民族的美好未来而奋斗，生命也就停止了。</span><span style="font-weight:normal;text-decoration:underline;"><span style="font-family:Tahoma;font-size:18px;">武将只是效忠皇帝本人，不能把自己的战斗成果和人民的解放和幸福结合起来，也会产生悲剧。</span><br/> </span><span style="font-family:Tahoma;font-size:18px;font-weight:normal;text-decoration:underline;">岳飞</span></span><span style="font-family:Tahoma;font-size:18px;text-decoration:underline;">死的天日昭昭，但是没有能够完成一生的心愿。如果能够拒绝当时的金牌令，揭露当时朝廷的卑鄙用心， 包括皇帝本不为百姓着想的卑鄙偏安的用心。把他们的罪行罗列出来，吧这个腐败 屈膝 的朝廷彻底的否定掉。打到漠北，赢取钦宗皇帝，废除赵构小皇帝，使得整个南宋在杭州的奸佞政权瓦解。辅佐钦宗重建新朝。或许还会延续南宋的历史更多时间。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 金人最后被元朝灭亡， 南宋也被元朝灭亡。一代天骄 忽必烈，成吉思汗等人，纵兵跃马，所向披靡，不知道在和文天祥对话的时候，是否想到过，他们南下不能逾越的岳飞和岳家军？</span><br/> <span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;"> 附： </span><span><br/> <span><span style="font-family:Tahoma;font-size:18px;">“冻杀不拆屋，饿杀不打掳”，“撼山易，撼岳家军难”</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;"> 关于岳飞的对联：</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 清代书画家秦文锦题岳飞墓联：</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 人从宋后少名桧 我到坟前愧姓秦</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 岳飞墓阙联</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 青山有幸埋忠骨 白铁无辜铸佞臣</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 在武昌蛇山有一座岳飞亭，亭的石柱上有一幅楹联：</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 撼山抑何易，撼军抑何难，愿忠魂常镇荆湖，护持江汉雄风，大业先从三户起；</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 文官不爱钱，武官不怕死，奉谠论复兴家国，留得乾坤正气，新猷端自四维张。</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;"> 西湖歌舞从此罢，南宋朝廷从此小</span><br/> <br/> </span></span><br/> <p style="color:#000000;text-indent:0px;"> <span style="font-family:Tahoma;font-size:18px;">在房东张大年的屏风上题词：</span></p> <blockquote style="color:#000000;text-indent:0px;"> <div style="margin:0px;padding:0px;"> <span style="font-family:Tahoma;font-size:18px;">近中原〔板〕荡，金贼长驱，如入无人之境；将帅无能，不及长城之壮。余发愤河朔，起自相台，总发从军，小大历二百余战。虽未及远涉夷荒，讨曲巢穴，亦且快国雠之万一。今又提一垒孤军，振起宜（兴），建康之城，一举而复，贼拥入江，仓皇宵遁，所恨不能匹马不回耳！ 今且休兵养卒，蓄锐待敌。如或朝廷见念，赐予器甲，使之完备，颁降功赏，使人蒙恩；即当深入虏庭，缚贼主碟血马前，尽屠夷种，迎二圣复还京师，取故地再上版籍。他时过此，勒功金石，岂不快哉！此心一发，天地知之，知我者知之。建炎四年六月望日，河朔岳飞书。</span> </div> </blockquote> <div style="margin:0px 0px 5px;padding:0px;color:#333333;"> <span style="font-family:Tahoma;font-size:18px;">向宋高宗赵构“上书数千言”，其略云：</span> </div> <div style="margin:0px 0px 5px;padding:0px;color:#333333;"> <div style="margin:0px 0px 10px;padding:0px 0px 3px 20px;"> <a href="http://baike.baidu.com/picview/2545/2545/0/63d9f2d3572c11df536ca465632762d0f703c233.html" target="_blank"></a> <p style="text-align:left;color:#555555;text-indent:0px;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;"> <span style="font-family:Tahoma;font-size:18px;">岳飞书法拓片</span></p> </div> <span style="font-family:Tahoma;font-size:18px;">陛下已登大宝，社稷有主，已足伐敌之谋。而勤王之师日集，彼方谓吾素弱，宜乘其怠击之。黄潜善、汪伯彦辈不能承圣意恢复，奉车驾日益南，恐不足系中原之望。臣愿陛下乘敌穴未固，亲率六军北渡，则将士作气，中原可复</span><br/> <span><br/> <span style="color:#333333;font-family:Tahoma;font-size:18px;">岳飞在班师途中得知噩耗，不由仰天悲叹：“所得诸郡，一旦都休！社稷江山，难以中兴！乾坤世界，无由再复！</span></span> </div> <span> <p style="color:#000000;text-indent:0px;"> <a href="http://zh.wikipedia.org/wiki/1135%E5%B9%B4" target="_blank"><span style="font-family:Tahoma;font-size:18px;">1135年</span></a><span style="font-family:Tahoma;font-size:18px;">，由于岳家军的兵力变成了原来的三倍，岳家军也从原先十将的编制扩充至三十将的编制</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-33" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[32]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">，每将的平均兵力是三千多人。到绍兴九年（</span><a href="http://zh.wikipedia.org/wiki/1139%E5%B9%B4" target="_blank"><span style="font-family:Tahoma;font-size:18px;">1139年</span></a><span style="font-family:Tahoma;font-size:18px;">）岳家军增至八十四将，每将的平均兵力减至一千二百余人。 岳家军至少有十二统制“军”：1.背嵬军；2.前军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-34" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[33]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；3.右军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-35" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[34]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；4.中军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-36" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[35]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；5.左军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-37" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[36]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；6.后军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-38" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[37]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；7.游奕军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-39" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[38]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；8.踏白军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-40" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[39]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；9.选锋军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-41" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[40]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；10.胜捷军；11.破敌军</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-42" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[41]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">；12.水军。其中背嵬军是绝对主力，名字学自韩世忠的同名统制军；游奕是巡回的意思；踏白是武装侦察的意思；其它军名都是增长士气的军号。</span></p> <p style="color:#000000;text-indent:0px;"> <span style="font-family:Tahoma;font-size:18px;">据绍兴九年（</span><a href="http://zh.wikipedia.org/wiki/1139%E5%B9%B4" target="_blank"><span style="font-family:Tahoma;font-size:18px;">1139年</span></a><span style="font-family:Tahoma;font-size:18px;">）统计，这十二军共有22名统制、5名统领和252名将官分别率领，其中有正将、副将和准备将各84名</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-43" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[42]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">。</span><a href="http://zh.wikipedia.org/wiki/%E7%8E%8B%E8%B4%B5_(%E5%8D%97%E5%AE%8B)" target="_blank"><span style="font-family:Tahoma;font-size:18px;">王贵</span></a><span style="font-family:Tahoma;font-size:18px;">任中军统制</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-44" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[43]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">，</span><a href="http://zh.wikipedia.org/wiki/%E5%BC%B5%E6%86%B2_(%E5%AE%8B)" target="_blank"><span style="font-family:Tahoma;font-size:18px;">张宪</span></a><span style="font-family:Tahoma;font-size:18px;">任前军统制</span><sup><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%A3%9B#cite_note-45" target="_blank"><span style="font-family:Tahoma;font-size:18px;">[44]</span></a></sup><span style="font-family:Tahoma;font-size:18px;">，这二人是岳飞的副手，岳飞不在时可代替岳飞指挥其他统制，主持岳家军全军的事务；</span><a href="http://zh.wikipedia.org/w/index.php?title=%E5%BE%90%E5%BA%86&amp;action=edit&amp;redlink=1" target="_blank"><span style="font-family:Tahoma;font-size:18px;">徐庆</span></a><span style="font-family:Tahoma;font-size:18px;">、</span><a href="http://zh.wikipedia.org/wiki/%E7%89%9B%E7%9A%8B" target="_blank"><span style="font-family:Tahoma;font-size:18px;">牛皋</span></a><span style="font-family:Tahoma;font-size:18px;">和</span><a href="http://zh.wikipedia.org/w/index.php?title=%E8%91%A3%E5%85%88&amp;action=edit&amp;redlink=1" target="_blank"><span style="font-family:Tahoma;font-size:18px;">董先</span></a><span style="font-family:Tahoma;font-size:18px;">三人最为善战；此五人是岳家军的中坚人物。]</span></p> <span> <p style="color:#000000;text-indent:0px;"> <span><span style="color:#333333;"><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">岳飞在狱中被赐死。在生命的最后一刻，岳飞无限悲痛地向天空仰视了一阵，接着就拿过笔来在供状上写了八个大字：『天日昭昭！天日昭昭！』</span><br/> </span><span style="font-family:Tahoma;font-size:18px;">当南宋广大人民知道岳飞被杀害的消息时，『天下冤之』、『皆为流涕』</span></span><br/> <span><span style="color:#000000;font-family:Tahoma;font-size:18px;">著名历史学家、宋史研究泰斗王曾瑜先生曾经指出：岳飞是宋朝三百二十年间最得军心和民心的将帅。在被解除兵权之前，岳飞所统率的岳家军有将官近三百人，有士卒十万人</span><br/> <span><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">《林泉野记》记载：『云、宪坐斩，并赐飞死，年三十九，妻子徙岭外，天下冤之。飞略知书传，礼士恤民，所至秋毫无犯，民不知兵。』</span><br/> <span><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">岳飞则是进攻型的将帅。</span><br/> <span><span style="color:#000000;font-family:Tahoma;font-size:18px;">南宋初年，具备光复故地的决心和能力的宋军统帅，惟有岳飞一人</span></span></span></span></span><br/> <br/> <span><span style="color:#000000;font-family:Tahoma;font-size:18px;">公元1140年（南宋绍兴十年，金国天眷三年）七月上旬和中旬，在最有利于金国女真骑兵发挥威力的天时和地利条件下，岳家军仍然能够以寡击众而取胜，先后在郾城之战和颍昌之战中击败金军主力，并乘胜进军至朱仙镇，迫使金军撤出东京开封府，这标志着宋金之间的战争形势发生了根本的转变。</span><br/> <span style="color:#000000;font-family:Tahoma;font-size:18px;"> 岳家军将士经过浴血奋战，接连击败金军，中原百姓纷纷出粮出力地支持岳家军，北方各路义军在金兵的后方攻城略地，北方各地的父老百姓也都争先恐后地牵牛挽车，“以馈义军”。金国自燕山以南，“号令不复行”。黄河以北的各路抗金义军正在等待着配合岳飞大军北进，——『河北忠义四十余万，皆以岳字号旗帜，愿公早渡河！』</span><br/> <span style="color:#000000;font-family:Tahoma;font-size:18px;"> 纵观北宋末年到公元1141年(南宋绍兴十一年)第二次宋金和议之前的宋金战争史，作为一个基本史实，其整体形势是宋军愈战愈强，而金军愈战愈弱。</span></span></span></span></span></p> <h3 style="color:#000000;text-indent:0px;"> <span style="font-family:Tahoma;font-size:18px;">《宋史》评价</span> </h3> <p style="color:#000000;text-indent:0px;"> <br/> <span style="color:#000000;font-family:Tahoma;font-size:18px;">善以少击衆。欲有所举，尽召诸统制与谋，谋定而后战，故有胜无败。猝遇敌不动，故敌为之语曰：“撼山易，撼岳家军难。”张俊尝问用兵之术，曰：“仁、智、信、勇、严，阙一不可。”调军食，必蹙额曰：“东南民力，耗敝极矣。”荆湖平，募民营田，又为屯田，岁省漕运之半。帝手书曹操、诸葛亮、羊祜三事赐之。飞跋其后，独指操为奸贼而鄙之，尤桧所恶也。西汉而下，若韩、彭、绛、灌之为将，代不乏人，求其文武全器、仁智并施如宋岳飞者，一代岂多见哉。史称关云长通《左氏春秋》学，然未尝见其文章。飞北伐，军至汴梁之朱仙镇，有诏班师，飞自为表答诏，忠义之言，流出肺腑，真有诸葛孔明之风，而卒死于秦桧之手。盖飞与桧势不两立，使飞得志，则金仇可复，宋耻可雪；桧得志，则飞有死而已。昔刘宋杀檀道济，道济下狱，嗔目曰：“自坏汝万里长城！”高宗忍自弃其中原，故忍杀飞，呜呼冤哉！呜呼冤哉！</span></p> </span><span style="color:#222222;font-family:Arial, Verdana, sans-serif;"><span> <h2 style="text-align:center;color:#2B2B2B;text-indent:0px;font-family:Verdana, Arial, Tahoma;font-size:24px;font-style:normal;"> <span style="font-family:Tahoma;font-size:18px;">文天祥评价岳飞</span> </h2> <p style="color:#000000;text-indent:0px;"> <strong><span style="font-family:Tahoma;font-size:18px;">岳先生，我宋之吕尚也。建功树绩，载在史册，千百世后，如见其生。至于笔法，若云鹤游天，群鸿戏海，尤足见干城之选，而兼文学之长，当吾世谁能及之。</span></strong></p> </span> <p style="color:#000000;text-indent:0px;"> <br/></p> </span> <p style="color:#000000;text-indent:0px;"> <span style="color:#000000;font-family:Tahoma;font-size:18px;">相传民间为解秦桧之恨，用面团做成他的形像丢入油锅里炸，称之为“油炸桧”，后来演变成今日的</span><a href="http://zh.wikipedia.org/wiki/%E6%B2%B9%E6%A2%9D" target="_blank"><span style="font-family:Tahoma;font-size:18px;">油条</span></a><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">。</span><br/> <span><span style="color:#000000;font-family:Tahoma;font-size:18px;">《</span><a href="http://zh.wikipedia.org/wiki/%E5%AE%8B%E5%8F%B2" target="_blank"><span style="font-family:Tahoma;font-size:18px;">宋史</span></a><span style="color:#000000;font-family:Tahoma;font-size:18px;">》载，秦桧因为憎恶岳州（今</span><a href="http://zh.wikipedia.org/wiki/%E6%B9%96%E5%8D%97" target="_blank"><span style="font-family:Tahoma;font-size:18px;">湖南</span></a><a href="http://zh.wikipedia.org/wiki/%E5%B2%B3%E9%98%B3%E5%B8%82" target="_blank"><span style="font-family:Tahoma;font-size:18px;">岳阳市</span></a><span style="color:#000000;font-family:Tahoma;font-size:18px;">）和岳飞的姓相同，</span><a href="http://zh.wikipedia.org/wiki/%E7%B4%B9%E8%88%88" target="_blank"><span style="font-family:Tahoma;font-size:18px;">绍兴</span></a><span style="color:#000000;font-family:Tahoma;font-size:18px;">二十五年（</span><a href="http://zh.wikipedia.org/wiki/1155%E5%B9%B4" target="_blank"><span style="font-family:Tahoma;font-size:18px;">1155年</span></a><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">）改为纯州，直到元末写《宋史》时仍然叫纯州。</span><br/> <span><a href="http://zh.wikipedia.org/wiki/%E6%96%87%E5%A4%A9%E7%A5%A5" target="_blank"><span style="font-family:Tahoma;font-size:18px;">文天祥</span></a><span style="color:#000000;font-family:Tahoma;font-size:18px;">云：“</span><a href="http://zh.wikipedia.org/wiki/%E7%A4%BE%E7%A8%B7" target="_blank"><span style="font-family:Tahoma;font-size:18px;">社稷</span></a><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">为重，君为轻，立君以存社稷，存一日则尽臣子一日之责。”</span><br/> <span><a href="http://zh.wikipedia.org/wiki/%E6%A2%81%E7%BE%BD%E7%94%9F" target="_blank"><span style="font-family:Tahoma;font-size:18px;">梁羽生</span></a><span style="color:#000000;font-family:Tahoma;font-size:18px;">在《</span><a href="http://zh.wikipedia.org/w/index.php?title=%E7%AC%94%E8%8A%B1%E5%85%AD%E7%85%A7&amp;action=edit&amp;redlink=1" target="_blank"><span style="font-family:Tahoma;font-size:18px;">笔花六照</span></a><span style="color:#000000;font-family:Tahoma;font-size:18px;">》中指出，“秦桧的‘南人归南，北人归北’是‘</span><a href="http://zh.wikipedia.org/wiki/%E4%B8%A4%E4%B8%AA%E4%B8%AD%E5%9B%BD" target="_blank"><span style="font-family:Tahoma;font-size:18px;">两个中国</span></a><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">’论调的祖宗”</span><br/> <span style="color:#333333;font-family:Tahoma;font-size:18px;">中国历史上的十大</span><a href="http://baike.baidu.com/view/754347.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">奸臣</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">（</span><a href="http://baike.baidu.com/view/390605.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">庆父</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、</span><a href="http://baike.baidu.com/view/36955.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">赵高</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、</span><a href="http://baike.baidu.com/view/54329.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">梁冀</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、</span><a href="http://baike.baidu.com/view/2664.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">董卓</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、</span><a href="http://baike.baidu.com/view/22444.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">来俊臣</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、</span><a href="http://baike.baidu.com/view/40696.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">李林甫</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、秦桧、</span><a href="http://baike.baidu.com/view/28663.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">严嵩</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、</span><a href="http://baike.baidu.com/view/19376.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">魏忠贤</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">、</span><a href="http://baike.baidu.com/view/19534.htm" target="_blank"><span style="font-family:Tahoma;font-size:18px;">和珅</span></a><span style="color:#333333;font-family:Tahoma;font-size:18px;">）</span><br/> </span></span></span></span></span></span></span><br/> <span><br/> <span style="font-family:Tahoma;font-size:18px;"> 岳飞自己的诗词</span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">满江红 岳飞</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">怒发冲冠，凭栏处潇潇雨歇。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">抬望眼，仰天长啸，壮怀激烈。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">三十功名尘与土，</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">八千里路云和月。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">莫等闲白了少年头，空悲切。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">靖康耻，犹未雪；</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">臣子恨，何时灭！</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">驾长车踏破贺兰山缺。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">壮志饥餐胡虏肉，</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">笑谈渴饮匈奴血。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">待从头收拾旧山河，朝天阙。</span><br/> <span style="font-weight:bold;"><span style="font-family:Tahoma;font-size:18px;">我来批驳下：（有人说这首满江红不是岳飞做的，这显然是不成立的，原因是：</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 大江东去浪淘尽千古风流人物 不是苏轼做的，那谁能代替苏东坡写出来这样的词句。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 沁园春雪 数风流人物 还看今朝 不是毛泽东谁能代替毛泽东写出来这样的词句。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 帘卷西风人比黄花廋 不是李清照谁能代替李清照写出来这样的词句。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 人生自古谁无死 留取丹心照汗青 不是文天祥谁能代替文天祥写出来这样的词句。</span><br/> <span style="font-family:Tahoma;font-size:18px;"> 如果岳飞不是历经百战，不是对战争的规律和最战略战术有十分精到的把握，这首满江红是写不出来的。 有的平庸的诗词，文人可以代替写出来，像这样的诗词 没有把整个国家中兴，人民幸福、一心报国的情怀 都始终装在心里，没有吧恢复故土的十分急切的愿望，是写不出来这样的诗词的，所以，能够在切合这首满江红的时间地点和人物， 只有岳飞，因为只有岳飞的经历可以支撑这首</span></span><span style="color:#000000;font-family:Tahoma;font-size:18px;">满江红意境、抱负和实践。）</span><br/> <br/> <span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">满江红 岳飞</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">遥望中原，荒烟外、许多城郭。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">想当年、花遮柳护，凤楼龙阁。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">万岁山前珠翠绕，蓬壶殿里笙歌作。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">到而今、铁蹄满郊畿，风尘恶。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">兵安在，膏锋锷。民安在，填沟壑。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">叹江山如故，千村寥落。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">何日请缨提锐旅，一鞭直渡清河洛。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">却归来、再续汉阳游，骑黄鹤。</span><br/> <span><br/> <br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">小重山 岳飞</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">昨夜寒蛩不住鸣。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">惊回千里梦，已三更。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">起来独自绕阶行。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">人悄悄，帘外月胧明。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">白首为功名。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">旧山松竹老，阻归程。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">欲将心事付瑶琴。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">知音少，弦断有谁听。</span><br/> <span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">从驾游内苑应制 岳飞</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">敕报游西内，春光霭上林。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">花围千朵锦，柳捻万株金。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">燕绕龙旗舞，莺随凤辇吟。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">君王多雨露，化育一人心。</span><span><br/> <span><br/> <br/> </span></span></span></span></span></span></span></span></span><span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">归赴行在过上竺寺偶题 岳飞</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">强胡犯金阙，驻跸大江南。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">一帝双魂杳，孤臣百战酣。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">兵威空朔漠，法力仗瞿昙。</span></span><br/> <span style="color:#000000;"><span style="font-family:Tahoma;font-size:18px;">恢复山河日，捐躯分亦甘。</span><br/> <br/> <span><span style="font-family:Tahoma;font-size:18px;">题雩都华严寺 岳飛 </span><br/> <span style="font-family:Tahoma;font-size:18px;"> 手持竹节访黄龙，旧穴空遗虎子踪。 云锁断崖无觅处，半山松竹撼秋</span>风 <br/> </span></span></span></p> </span></span></span></span></span></span></span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 141, '沁园春 长征', '../upload/image/20180923/20180923102424_96423.jpg', '<p></p><p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">沁园春 长征</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">长征二万，历尽艰险，红军保全。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">想遵义会议，乾坤扭转，</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">四渡赤水，跳脱围歼，</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">大渡河上，金沙江里，</span></strong><strong><span style="font-family:Tahoma;font-size:18px;">围追堵截炸弹繁。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">置绝境，过雪山草地，三军入陕。</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;"> 西北金瓯重现</span></strong><strong><span style="font-family:Tahoma;font-size:18px;">，人类历史第一篇。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">正日军侵华，国共对峙</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">民生凋敝，红军少年。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">集中优势，避实就虚，</span></strong><strong><span style="font-family:Tahoma;font-size:18px;">以少胜多战旗妍。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Tahoma;font-size:18px;">八十载，犹历历在目，影响深远。</span></strong></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 142, '清明节感怀', '../upload/image/20180923/20180923102453_81400.jpg', '<p></p><p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">清明节感怀</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">五四风云叱咤声，民族精神猛警醒。北伐一役惩腐恶，中华大地滚雷霆。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">十年围困井冈山，星星之火竟燎原。长征二万路漫漫，铸炼红军心不散。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">日寇侵华战端开，华北狼烟东北来。接天蔽日如蝗虫，烧杀掠淫更无情。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">上海南京恨失守，武汉告急重庆走。德国出兵二百万，侵入苏俄来天半。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">珍珠岛上未黎明，日军战机裂长空。世人惶惶皆束手，难料战争要持久。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">一时乌云被拨开，国共和谈呼出来。一纸和谈展眼空，战斧霍霍起山东。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">排山倒海势如峰，百年国脉再刀兵。北线攻克锦州城，五十万人置瓮中，</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">南线淮海看徐蚌，五大精英全丧命。平津战罢渡江来，飘摇南京旗展开。</span></strong></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="font-family:Microsoft YaHei;font-size:18px;">台海两地从此隔，共同发展促和平。石碑重重复重重，无限相思在清明。</span></strong></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 143, '工作小感', '../upload/image/20180923/20180923102518_65766.jpg', '<p></p><p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">工作小感</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">1. 公司小感</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">数载外贸进出口，款进款出货物走。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">价涨价跌寻常事，有利无利不堪愁。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">孤鸿争与云并立，小司敢泛大潮流。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">他日“五百强”上客，始慰当初一运筹！</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">注：五百强----指世界五百强企业。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">2. 个人小感</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">毕业至今苦奔忙，就业创业两相当。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">上海浦东见客户，安徽合肥去工厂。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">单据单证如流水，空运海运直通航。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">记挂提单何日到，不由致电问联邦。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">注：联邦----指FEDEX联邦快递。</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 144, '江淮烈士陵园有感', '../upload/image/20180923/20180923102533_43725.jpg', '<p></p><p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">2010年10月5日 到合肥江淮烈士陵园有感</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">今日清晨，到合肥江淮烈士陵园，天空霞光万丈，四野桂花飘香，我们拾级而上，迎面看到“江淮烈士永垂不朽”的题词（邓小平题）。瞻仰后，赋诗3首。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">烈士陵园忆当年，中华大地起硝烟。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">日寇机枪如雨下，蒋军屠刀乱家园。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">前仆后继英雄血，改天换地报国情，</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">民族独立纪念日，不畏牺牲万古传。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">抗日战争</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">吞并华北和中原，又侵台湾与海南。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">日蹄踏碎山河梦，国军让出半边天。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">熊熊战火烧不尽，活活生灵血流泉。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">英魂忠烈留千古，铁辑沉沙埋万年。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">解放战争</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">淮海战端开，新国曙光来。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">华野出碾庄，中野扼蚌淮。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">双堆捉黄维，徐州扫残埃。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">一锅夹生饭，味美色不衰。</span></p> <p style="color:#444444;text-indent:0px;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 145, '长江断想  五绝', '../upload/image/20180923/20180923102600_34864.jpg', '<p></p><p><span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">长江断想 五绝</span></p> <p><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">目极长江水，</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">情动九州潮。</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">声断南归雁，</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">古今一梦遥。</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 146, '写宋庆龄 五律', '../upload/image/20180923/20180923102616_96868.jpg', '<p></p><p><span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">写宋庆龄 五律</span></p> <p><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">金銮别玉女，</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">飘落至凡间。</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">眉锁山河恨，</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">心忧疆土全。</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">桃蕊留轻雾，</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">新荷啄绿瑗。</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">永续民国志，</span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">生死两茫然。</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 147, '凤凰广场咏怀', '../upload/image/20180923/20180923102630_58186.jpg', '<p></p><div style="margin:0px;padding:0px;color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:Microsoft YaHei;font-size:18px;">凤凰广场咏怀</span> </div> <div style="margin:0px;padding:0px;color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> </div> <div style="margin:0px;padding:0px;color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-family:宋体;font-size:18px;"><span style="font-family:Microsoft YaHei;font-size:18px;">凤凰广场势巍巍，</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 徽州大道纳雄魁。</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 东渐薄膜甲天下，</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 亚太集团外单肥。</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 合肥南站收眼底，</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 巢湖港湾万轮回。</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 今日挥泪辞黄鹤，</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 又伴鹰隼誓天飞。</span></span> </div>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 148, '咏 天鹅湖', '../upload/image/20180923/20180923102646_96423.jpg', '<p><span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:bold;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;"> <p><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">（天鹅湖，在合肥政务区）</span></p> <p></p> </span></span></p><p><span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:bold;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">咏 天鹅湖--自然风光（绿）</span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:bold;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">碧雾氤氲荡绿烟，岛出湖心迷点帆。</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 幽径分得左右水，浮桥绣出上下滩。</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 柔波皱卷山腰树，沁芳香锁岸底船。</span><br/> <span style="font-family:Microsoft YaHei;font-size:18px;"> 柳拂茜裙风送晚，折却连理对红颜。</span></span><span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></span><br/> <br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:bold;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">咏 天鹅湖--社会风光（忙）</span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:bold;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">何来碧波无根源？赊来长江水一潭。</span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:bold;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">波色连江起翠雾，绿茵遍地染山川。</span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:bold;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">贵妃忘却华清池，西子恨别杭州湾。</span></span><br/> <span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:bold;background-color:#FFFFFF;">而今环湖楼群立，喜得商贾虎翼添。</span><span style="color:#444444;font-family:Microsoft YaHei;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></span><br/> <br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">（自己解释：</span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">何来碧波无根源，赊来长江水一潭。---哪里来的合肥经济的发展， 借的长江三角的经济发展辐射。</span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">波色连江起翠雾，绿茵遍地染山川。 ----一片商业繁忙的现代化都市。</span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">贵妃忘却华清池，西子恨别杭州湾。----国内外招商引资投资者云集 。 </span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="font-family:Microsoft YaHei;font-size:18px;">而今环湖楼群立，喜得商贾虎翼添。---商业的现状。 </span>）</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (52, 149, '沁园春  国际贸易', '../upload/image/20180923/20180923102706_67617.jpg', '<p></p><p><span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong>沁园春 国际贸易</strong></span><span class="Apple-converted-space" style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong> </strong></span></span></p> <p><span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong>中国制造，质硬量足，物美价廉。</strong></span><span class="Apple-converted-space" style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong> </strong></span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong>望长江三角，货物如山，</strong></span><span class="Apple-converted-space" style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong> </strong></span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong>粤港码头，尺柜连绵，</strong></span><span class="Apple-converted-space" style="color:#000000;font-family:Microsoft YaHei;font-size:18px;"><strong> </strong></span></span><br/> <span style="color:#444444;font-family:punctuation, 微软雅黑, Tohoma;font-size:14px;font-style:normal;font-weig